def _xirr(cashflows: list[tuple[date, float]]) -> float | None:
    if len(cashflows) < 2:
        return None
    start = cashflows[0][0]
    times = [max((day - start).days, 0) / 365.0 for day, _amount in cashflows]
    amounts = [amount for _day, amount in cashflows]

    def npv(rate: float) -> float:
        return sum(amount / (1 + rate) ** time for amount, time in zip(amounts, times, strict=True))

    def dnpv(rate: float) -> float:
        return sum(
            -time * amount / (1 + rate) ** (time + 1) for amount, time in zip(amounts, times, strict=True)
        )

    rate = 0.1
    for _ in range(60):
        value = npv(rate)
        slope = dnpv(rate)
        if abs(slope) < 1e-12:
            break
        nxt = rate - value / slope
        nxt = min(max(nxt, -0.9), 5.0)
        if abs(nxt - rate) < 1e-10:
            rate = nxt
            break
        rate = nxt
    if not math.isfinite(rate) or abs(npv(rate)) > 1e-3:
        return None
    return rate

